"""Test harness: build scenarios, run bridge, assert ledger + pipeline shape."""
import json, subprocess, sys, os

BRIDGE = '/app/submission/bridge.py'

def run(scenario):
    proc = subprocess.run([sys.executable, BRIDGE], input=json.dumps(scenario).encode(),
                          stdout=subprocess.PIPE, stderr=subprocess.PIPE, timeout=30)
    if proc.returncode:
        raise AssertionError('crash: ' + proc.stderr.decode()[:2000])
    return json.loads(proc.stdout)

def stream(sid, fields=None, data=None, unknown=None, trailing=None, terminal='fin'):
    ev = []
    if unknown is not None:
        for ft, hx in unknown:
            ev.append({'sid': sid, 'type': 'unknown', 'frame_type': ft, 'hex': hx})
    if fields is not None:
        ev.append({'sid': sid, 'type': 'headers', 'fields': fields})
    for chunk in (data or []):
        ev.append({'sid': sid, 'type': 'data', 'hex': chunk})
    if trailing is not None:
        ev.append({'sid': sid, 'type': 'headers', 'fields': trailing})
    ev.append({'sid': sid, 'type': terminal})
    return ev

def base_fields(method='GET', scheme='https', authority='demo.test', path='/', extra=()):
    f = [[':method', method], [':scheme', scheme], [':authority', authority], [':path', path]]
    f.extend([list(p) for p in extra])
    return f

def rec(sid, status, **kw):
    d = {'sid': sid, 'status': status, 'commit_at': None, 'origin': None,
         'offset': None, 'length': 0, 'cache_key': None}
    d.update(kw)
    return d

def parse_pipeline(raw):
    """Independent H1 parse; returns list of request dicts."""
    out = []
    pos = 0
    while pos < len(raw):
        start = pos
        def readline(p):
            e = raw.index(b'\r\n', p)
            return raw[p:e], e + 2
        reqline, pos = readline(pos)
        fields = []
        while True:
            line, pos = readline(pos)
            if not line:
                break
            n, v = line.split(b': ', 1)
            fields.append((n, v))
        d = dict(fields)
        body = b''
        trailers = []
        if d.get(b'transfer-encoding') == b'chunked':
            while True:
                sz, pos = readline(pos)
                n = int(sz, 16)
                if n == 0:
                    break
                body += raw[pos:pos+n]
                assert raw[pos+n:pos+n+2] == b'\r\n', 'bad chunk terminator'
                pos += n + 2
            while True:
                line, pos = readline(pos)
                if not line:
                    break
                trailers.append(line)
        else:
            n = int(d[b'content-length'])
            body = raw[pos:pos+n]
            assert len(body) == n
            pos += n
        out.append({'offset': start, 'length': pos - start, 'request': reqline,
                    'fields': fields, 'body': body, 'trailers': trailers})
    return out

FAILS = []
def check(name, scenario, expect_streams=None, expect_origins=None, extra=None):
    try:
        got = run(scenario)
    except Exception as exc:
        FAILS.append((name, 'exception %r' % (exc,)))
        print('FAIL(exc)', name, exc)
        return None
    ok = True
    msgs = []
    if expect_streams is not None:
        if got['streams'] != expect_streams:
            ok = False
            msgs.append('streams:\n  got      %s\n  expected %s' % (json.dumps(got['streams']), json.dumps(expect_streams)))
    if expect_origins is not None:
        got_o = {k: bytes.fromhex(v) for k, v in got['origins'].items()}
        if got_o != expect_origins:
            ok = False
            for k in sorted(set(got_o) | set(expect_origins)):
                if got_o.get(k) != expect_origins.get(k):
                    msgs.append('origin %s:\n  got      %r\n  expected %r' % (k, got_o.get(k), expect_origins.get(k)))
    if extra is not None:
        try:
            extra(got)
        except Exception as exc:
            ok = False
            msgs.append('extra: %r' % (exc,))
    if not ok:
        FAILS.append((name, '\n'.join(msgs)))
        print('FAIL', name)
        for m in msgs:
            print('   ', m)
    else:
        print('ok  ', name)
    return got

def summary():
    print()
    if FAILS:
        print('%d FAILURES' % len(FAILS))
        sys.exit(1)
    print('ALL PASSED')
